/* Visible-entry clocks keep charge tells and shots inside the real camera. */
static int aircraft_weapon_role(int type){return type==16||type==25||type==27||type==28;}
static float aircraft_beam_distance(float x,float y,float ax,float ay,float bx,float by){float dx=bx-ax,dy=by-ay,d=dx*dx+dy*dy;if(d<1)return 100000;float u=((x-ax)*dx+(y-ay)*dy)/d;if(u<0||u>1)return 100000;return fabsf((x-ax)*dy-(y-ay)*dx)/sqrtf(d);}
static void aircraft_beam_end(const Obj*o,float*x,float*y){float dx=(o->aimX-o->x)/(float)Q,dy=(o->aimY-o->y)/(float)Q,d=hypotf(dx,dy);if(d<1){dx=0;dy=1;d=1;}*x=o->x/(float)Q+dx*700/d;*y=o->y/(float)Q+dy*700/d;if(cavern_phase(ex.phase)){float sx=o->x/(float)Q,sy=o->y/(float)Q;for(int k=4;k<=700;k+=4){float xx=sx+dx*k/d,yy=sy+dy*k/d;if(xx<tunnel_left((int)yy)+2||xx>tunnel_right((int)yy)-2){*x=sx+dx*(k-4)/d;*y=sy+dy*(k-4)/d;break;}}}}
static void aircraft_weapon_step(Obj*o){if(!enemy_damageable(o))return;int c=++o->weaponClock%160;if(c==1){o->aimX=g.px;o->aimY=player_y;}if(o->type==27){if(c==40){o->weaponShots++;pc_laser_sound(2,o->x/Q);}if(c>=40&&c<54){float xx,yy;aircraft_beam_end(o,&xx,&yy);if(aircraft_beam_distance(g.px/(float)Q,player_y/(float)Q,o->x/(float)Q,o->y/(float)Q,xx,yy)<player_hull_rx()+3)hurt_amount(g.px/Q,player_y/Q,0,1,50,1);}return;}if(c!=40)return;int dx=o->aimX-o->x,dy=o->aimY-o->y,d=absn(dx)+absn(dy);if(!d)d=1;Obj*b=bullet(o->x,o->y,dx*640/d,dy*640/d);if(!b)return;b->type=o->type==16?8:o->type==28?7:9;b->hp=o->type==16?4:3;b->aimX=o->aimX;b->aimY=o->aimY;o->weaponShots++;if(b->type==8){b->vx=(b->aimX-b->x)/60;b->vy=(b->aimY-b->y)/60;pc_mine_sound(o->x/Q);}else if(b->type==7)pc_torpedo_sound(0,o->x/Q);else pc_emp_sound(0,o->x/Q);}
static void aircraft_step(Obj*o){if(o->weaponClock<340){o->x=o->base*Q+sn(o->age+o->phase)*3;o->y+=o->y<(play_min_y()+65)*Q?340:35;}else o->y-=650;aircraft_weapon_step(o);}
